"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66898"],{84972(e){e.exports=JSON.parse('{"id":"F492","slug":"short-term-fee-apr","name":"Consumer Protection: Annualized Cost of a Short-Term Fee","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Consumer financial protection","level":"Beginner","aliases":["consumer financial protection","payday loan APR","overdraft fee APR","truth in lending","cost of credit disclosure"],"formula":{"latex":"APR=\\\\frac{\\\\text{Fee}}{\\\\text{Amount}}\\\\times\\\\frac{365}{\\\\text{Days}},\\\\quad EAR=\\\\left(1+\\\\frac{\\\\text{Fee}}{\\\\text{Amount}}\\\\right)^{365/\\\\text{Days}}-1","also":[],"text":"Simple annualized rate = (fee / amount borrowed) x (365 / days borrowed); Effective annual rate if the loan is rolled over again and again = (1 + fee / amount)^(365 / days) - 1; Consumer rules require firms to disclose the annual percentage rate so short-term products can be compared with other credit"},"symbols":[{"symbol":"Fee","meaning":"Charge for borrowing (interest and fees)","unit":"money"},{"symbol":"Amount","meaning":"Amount borrowed","unit":"money"},{"symbol":"Days","meaning":"Length of the loan in days","unit":"days"}],"when_to_use":"Use it to see the true cost of an overdraft fee or a payday loan. A fee that looks small becomes a very high rate once it is expressed per year, which is why laws require the rate to be shown (Truth in Lending in the US) and why some places cap it. Use the rolled-over rate only if the borrower really renews every time.","worked_example":{"problem":"A payday lender charges 35 to lend 100 for 7 days.","inputs":{"f":35,"a":100,"d":7},"steps":[{"label":"Fee as a share of the amount","working":"35 / 100","value":"35.0%"},{"label":"Simple annualized rate","working":"0.35 x 365 / 7","value":"1825%"},{"label":"Effective rate if rolled over","working":"(1+0.35)^(365 / 7)-1","value":"625136709%"},{"label":"Annualized rate if the same fee covered 30 days","working":"0.35 x 365 / 30","value":"426%"}],"answer":"The fee is 35.0% of the amount. Annualized, the rate is 1825%. If the loan were rolled over every week for a year the effective rate would be 625136709%. The same fee on a 30-day loan would be 426% a year."},"calculator":{"available":true,"inputs":[{"id":"f","label":"Fee","unit":"money","type":"number","default":35,"hint":""},{"id":"a","label":"Amount borrowed","unit":"money","type":"number","default":100,"hint":""},{"id":"d","label":"Days","unit":"days","type":"number","default":7,"hint":"","min":1}],"checks":[{"expr":"a>0 and d>0","message":"Amount and days must be above zero."}],"steps":[{"id":"pct","label":"Fee as a share of the amount","expr":"f/a","format":"pct1"},{"id":"apr","label":"Simple annualized rate","expr":"pct*365/d","format":"pct0"},{"id":"ear","label":"Effective rate if rolled over","expr":"(1+pct)^(365/d)-1","format":"pct0"},{"id":"apr30","label":"Annualized rate if the same fee covered 30 days","expr":"pct*365/30","format":"pct0"}],"results":["pct","apr","ear","apr30"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pct":0.35,"apr":18.249999999999996,"ear":6251367.0893413965,"apr30":4.258333333333333}},"finder":{"finds":"The annual rate hidden in a short-term fee","needs":"Fee, amount, days"},"related":[{"slug":"ear-to-apr","name":"Converting EAR to a Periodic Rate and APR"},{"slug":"ear","name":"Effective Annual Rate (EAR)"},{"slug":"good-debt-test","name":"Good Debt vs Bad Debt Test"}],"related_ids":["F023","F024","F101"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mtext>Fee</mtext><mtext>Amount</mtext></mfrac><mo>\xd7</mo><mfrac><mn>365</mn><mtext>Days</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>E</mi><mi>A</mi><mi>R</mi><mo>=</mo><msup><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>+</mo><mfrac><mtext>Fee</mtext><mtext>Amount</mtext></mfrac><mo fence=\\"true\\">)</mo></mrow><mrow><mn>365</mn><mi mathvariant=\\"normal\\">/</mi><mtext>Days</mtext></mrow></msup><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">APR=\\\\frac{\\\\text{Fee}}{\\\\text{Amount}}\\\\times\\\\frac{365}{\\\\text{Days}},\\\\quad EAR=\\\\left(1+\\\\frac{\\\\text{Fee}}{\\\\text{Amount}}\\\\right)^{365/\\\\text{Days}}-1</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"laspeyres-cpi","name":"Consumer Price Index (Laspeyres) and Substitution Bias"},"next":{"slug":"continuous-compounding","name":"Continuous Compounding"},"lesson":null,"total":522}')}}]);